import{q as h,k as g,c as i,b as t,e as r,s as c,d as y,t as f,m as a,g as n,w as k,_ as b,o as l}from"./CC6MPIJW.js";import{u as w,_ as v}from"./DiKHISIb.js";const I={class:"section-padding"},_={class:"container thinnest-content"},D={class:"mb-3"},W=["src","alt"],N={__name:"eliminate-automate-delegate-do",setup(S){const m=h(),{currentRoute:d}=m,o=g.find(s=>s.slug===d.value.fullPath.replace("/articles/",""));return w(o),(s,e)=>{const u=b,p=v;return l(),i("section",I,[t("div",_,[t("div",null,[t("h1",D,f(a(o).title),1),a(o).image!=="title.jpg"?(l(),i("img",{key:0,src:`/img/articles/${a(o).image}`,alt:a(o).title,class:"mb-3"},null,8,W)):c("",!0),e[3]||(e[3]=y("<p>Some tasks engage and energize us. Others give our work meaning. Unfortunately, these tasks are often buried under a stack of less important stuff. They crowd our to-do list and demand our attention.</p><p>When I start to feel like I have too much work on my plate, I use a simple task-management framework—Eliminate, Automate, Delegate, Do—to get organized and to be productive.</p><p>It can do the same for you.</p><h2>Eliminate</h2><p>What tasks can simply not be done?</p><p>What would happen if you didn&#39;t attend a meeting? What if you stopped managing your social media for a week, let a few tasks go unfinished, or ignored metrics? What if you stopped treating every email like it was urgent?</p><p>We waste an incredible amount of time doing things that don&#39;t matter. Most people aren&#39;t overwhelmed because they&#39;re doing too many difficult or challenging things—they&#39;re overwhelmed because they&#39;re doing too many unnecessary things.</p><p>If something doesn&#39;t need to be done, don&#39;t do it.</p><h2>Automate</h2><p>If it has to be done, can it be automated?</p><p>We tolerate a lot of repetitive tasks because they don&#39;t seem worth fixing. Manually paying bills, copying data between spreadsheets, transcribing meeting notes, sending reminder emails—these are all low-leverage tasks that take up our time and energy.</p><p>If a task happens more than once, it deserves a system. That system might be as simple as an email filter, a calendar reminder, a template, or a script. It doesn&#39;t need to be technical or complicated. Something as simple as auto-pay can help to automate easy, repeatable tasks.</p><p>Take time to automate tasks that you do over and over again.</p><h2>Delegate</h2><p>If a task can&#39;t be automated, can someone else handle it?</p><p>Sometimes, other people are more efficient, better equipped, or have greater bandwidth to handle certain tasks. Delegation means giving a task to someone else and trusting them to get it done without you being directly involved. If you can&#39;t let other people work without your input, then it isn&#39;t delegation.</p><p>Delegation isn&#39;t about dumping work on others—it&#39;s about recognizing when someone else is better positioned to handle something so you can focus on what only you can do. If you need help, ask for it. Play to people&#39;s strengths, and let them play to yours. Don&#39;t delegate out of laziness.</p><p>If there is something that needs to be done, but not necessarily by you, look for opportunities to delegate.</p><h2>Do</h2><p>You should now have a clear list of things to do.</p>",20)),t("p",null,[e[1]||(e[1]=n("Set aside dedicated blocks of time, eliminate distractions, and ")),r(u,{to:"/articles/improve-focus-actionable-ways"},{default:k(()=>e[0]||(e[0]=[n("focus on one thing at a time")])),_:1}),e[2]||(e[2]=n(". Group similar tasks together—answering all your emails in one session, for example—to minimize context switching. When you're working on something that requires deep concentration, resist the urge to respond to messages or switch tasks."))]),e[4]||(e[4]=t("h2",null,"Why This System Works",-1)),e[5]||(e[5]=t("p",null,"When I'm not buried in busy work, I gain clarity. I can take time to step back, look at the big picture, and make adjustments to my plans. This system helps me to do that.",-1)),e[6]||(e[6]=t("p",null,"Spend less time doing unimportant tasks and more time on the good stuff. Eliminate unnecessary work. Automate repetitive tasks. Delegate what doesn't require your direct involvement. Free yourself up to focus on what matters most.",-1)),e[7]||(e[7]=t("p",null,"Eliminate. Automate. Delegate. Do.",-1))]),r(p,{slug:a(o).slug},null,8,["slug"])])])}}};export{N as default};
